  async generatePdfFromHtml(data: any): Promise<Uint8Array> {

    console.log({data})
    
    const craftOfBuilding = this.buildCraftOfBuilding(data.areas, data.designOptions);

    const materialsOfBuilding = data.materials.map(mat => ({
      item: mat.item,
      totalPrice: mat.totalPrice
    }));

    // const browser = await puppeteer.launch({ headless: true }); // ← cambiado
    const browser = await puppeteer.launch({
      headless: true,
      args: ['--no-sandbox', '--disable-setuid-sandbox']
    });

    const page = await browser.newPage();

    const html = this.buildHtml(data, craftOfBuilding, materialsOfBuilding);

    await page.setContent(html, { waitUntil: 'networkidle0' });

    await page.waitForSelector('.mermaid svg', {
      timeout: 10000
    });

    const pdfBuffer = await page.pdf({
      format: 'A4',
      printBackground: true,
      displayHeaderFooter: true,
      headerTemplate: `
        <div style="font-size:10px; text-align:left; width:100%; margin-top:0px;">  
        <img src="data:image/png;base64," alt="Company Logo" style="max-width: 150px; margin-left: 18px; margin-top: -25px; width: 150px; height: auto;">
        </div>
        `,
        footerTemplate: `
        <div style="font-size:10px; text-align:center; width:100%;">
        </div>
        `,
        margin: {
          top: '150px',
          bottom: '40px',
        },
      });
      
      /* <img src="http://localhost:3001/images/alpine-logo.png" 
        alt="Company Logo" 
        style="width: 180px; height: auto;" 
      > */
    await browser.close();
    return pdfBuffer; // ← ahora es Uint8Array, y está bien
  }

